#!/usr/bin/env bash
# Build the Calkit arm in calkit/, the way a coding agent following the
# calkit:conventions skill would: raw data added, environment, questions
# declared first, pipeline stages, run, answers citing evidence through
# placeholders, and the report generated by a stage. Then the corrected
# sessions export replaces the original, and the pipeline reruns, which
# updates the report and answers with nothing retyped.
set -euo pipefail
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
source "$ROOT/scripts/versions.env"
unset VIRTUAL_ENV
calkit() { uv run -q --project "$CALKIT_REPO" calkit "$@"; }
export GIT_AUTHOR_NAME="Audit Builder" GIT_AUTHOR_EMAIL="builder@example.org"
export GIT_COMMITTER_NAME="Audit Builder" GIT_COMMITTER_EMAIL="builder@example.org"
PROJ="$ROOT/calkit"
if [ -d "$PROJ" ]; then rm -rf "$PROJ"; fi
mkdir -p "$PROJ"/{scripts,data/raw}
cd "$PROJ"
git init -q -b main
calkit init
# Raw data as received, and the codebook
cp "$ROOT/build-data/participants.csv" data/raw/participants.csv
cp "$ROOT/build-data/sessions_v1.csv" data/raw/sessions.csv
cp "$ROOT/build-data/codebook_v1.md" codebook.md
calkit add data/raw
git add codebook.md
git commit -q -m "Add raw participant and session data with codebook"
# Analysis code and report template
cp "$ROOT"/shared/{prepare_data,fit_model,make_figure,write_report}.py scripts/
cp "$ROOT/shared/report_template.md" report_template.md
git add scripts report_template.md
git commit -q -m "Add analysis scripts and report template"
# Environment
# shellcheck disable=SC2086
calkit new uv-env -n main --python "$PYTHON_VERSION" $PACKAGES
# Questions, declared before the analysis runs
calkit new question "Does computerized cognitive training raise cognitive scores in older adults?" --commit
calkit update question 1 \
  --hypothesis "Training raises week-12 cognitive scores relative to waitlist control." \
  --approach "ANCOVA: OLS of week-12 score on arm, baseline score, age per 10 years, and education (secondary as reference), in participants with a scored baseline and week-12 assessment."
calkit new question "Is the training effect robust to analyzing change from baseline instead?" --commit
calkit update question 2 \
  --hypothesis "The change-score estimate is close to the ANCOVA estimate." \
  --approach "OLS of change in score from baseline to week 12 on arm, age, and education."
calkit new question "How do week-12 scores differ by education and age?" --commit
calkit update question 3 \
  --hypothesis "Participants with more education gain more by week 12, and older participants gain less." \
  --approach "Education and age coefficients of the ANCOVA model, with secondary education as the reference category."
git add calkit.yaml && git commit -q -m "Declare questions and approaches"
# Pipeline
calkit new python-script-stage -n prepare-data -e main \
  -s scripts/prepare_data.py \
  --arg=--participants --arg=data/raw/participants.csv \
  --arg=--sessions --arg=data/raw/sessions.csv \
  --arg=--out --arg=data/analysis.csv \
  -i data/raw/participants.csv -i data/raw/sessions.csv \
  -o data/analysis.csv --no-check --no-commit
calkit new python-script-stage -n fit-model -e main \
  -s scripts/fit_model.py \
  --arg=--data --arg=data/analysis.csv \
  --arg=--adjustment --arg='{adjustment}' \
  --arg=--out --arg='results/model-{adjustment}.json' \
  --iter adjustment ancova,change \
  -i data/analysis.csv \
  --out-git 'results/model-{adjustment}.json' --no-check --no-commit
calkit new python-script-stage -n make-figure -e main \
  -s scripts/make_figure.py \
  --arg=--data --arg=data/analysis.csv \
  --arg=--out --arg=results/score_by_week.png \
  -i data/analysis.csv \
  --out-git results/score_by_week.png --no-check --no-commit
calkit new python-script-stage -n write-report -e main \
  -s scripts/write_report.py \
  --arg=--primary --arg=results/model-ancova.json \
  --arg=--sensitivity --arg=results/model-change.json \
  --arg=--template --arg=report_template.md \
  --arg=--figure --arg=score_by_week.png \
  --arg=--out --arg=results/report.md \
  -i results/model-ancova.json -i results/model-change.json \
  -i report_template.md -i results/score_by_week.png \
  --out-git results/report.md --no-check --no-commit
git add -A && git commit -q -m "Add pipeline"
calkit run
calkit commit -m "Run pipeline"
# Answers citing the results as evidence
uv run -q --project "$CALKIT_REPO" python "$ROOT/scripts/calkit/add_answers.py" calkit.yaml
calkit check questions
git add -A && git commit -q -m "Answer questions with pipeline evidence"
# Corrected sessions export replaces the original
cp "$ROOT/build-data/sessions_v2.csv" data/raw/sessions.csv
cp "$ROOT/shared/codebook.md" codebook.md
calkit add data/raw/sessions.csv codebook.md
git commit -q -m "Use corrected sessions export with week-12 form B rescored"
calkit status || true
calkit run
calkit commit -m "Run pipeline"
calkit check questions
git status --short
git log --oneline
